const mongoose=require('mongoose');const schema=new mongoose.Schema({userId:{type:mongoose.Schema.Types.ObjectId,required:true,index:true},storeName:{type:String,required:true,trim:true},email:{type:String,required:true,lowercase:true,trim:true},phone:String,storeAddress:{type:String,required:true},status:{type:String,enum:['APPLIED','VERIFIED','REJECTED','UNVERIFIED'],default:'APPLIED'},verifiedAt:Date},{timestamps:true});schema.index({userId:1},{unique:true});module.exports=mongoose.model('Vendor',schema);
